import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:core_permission/core_permission.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:record/record.dart';

import '../config/interpretation_config.dart';
import '../model/interpretation_entry.dart';
import '../model/interpretation_state.dart';

/// ViewModel: WebSocket ASR session + microphone stream.
class InterpretationController extends Notifier<InterpretationState> {
  WebSocket? _socket;
  StreamSubscription<Uint8List>? _audioSub;
  final _recorder = AudioRecorder();

  @override
  InterpretationState build() => const InterpretationState();

  Future<void> start() async {
    if (state.isRunning) return;
    state = const InterpretationState(status: InterpretationStatus.connecting);

    final permResult = await ref
        .read(permissionServiceProvider)
        .request(AppPermission.microphone);
    if (permResult case Failure(:final error)) {
      state = InterpretationState(
        status: InterpretationStatus.error,
        error: InterpretationError(
          kind: InterpretationErrorKind.microphoneFailed,
          detail: error.message,
        ),
      );
      return;
    }

    final config = ref.read(interpretationConfigProvider);

    try {
      _socket = await WebSocket.connect(
        config.wssUrl,
        headers: {
          'Authorization': config.authorization,
          'apikey': config.apiKey,
        },
      );
    } catch (e) {
      state = InterpretationState(
        status: InterpretationStatus.error,
        error: InterpretationError(
          kind: InterpretationErrorKind.connectionFailed,
          detail: e.toString(),
        ),
      );
      return;
    }

    _socket!.listen(
      handleServerMessage,
      onError: _onSocketError,
      onDone: _onSocketDone,
    );

    _sendConfig(config);

    // ponytail: PCM stream — upgrade path is AudioEncoder.opus + audio_type:"opus".
    try {
      final audioStream = await _recorder.startStream(
        const RecordConfig(
          encoder: AudioEncoder.pcm16bits,
          sampleRate: 16000,
          numChannels: 1,
        ),
      );
      _audioSub = audioStream.listen(
        (chunk) => _socket?.add(chunk),
        onError: _onSocketError,
      );
    } catch (e) {
      await _closeSocket();
      state = InterpretationState(
        status: InterpretationStatus.error,
        error: InterpretationError(
          kind: InterpretationErrorKind.microphoneFailed,
          detail: e.toString(),
        ),
      );
      return;
    }

    state = state.copyWith(status: InterpretationStatus.running, entries: [], clearError: true);
  }

  Future<void> stop() async {
    if (!state.isRunning) return;
    try {
      _socket?.add(jsonEncode({'end': true}));
    } catch (_) {}
    await _audioSub?.cancel();
    await _recorder.stop();
    await _closeSocket();
    state = state.copyWith(status: InterpretationStatus.idle);
  }

  void _sendConfig(InterpretationConfig config) {
    final params = {
      'from': config.fromLanguageId,
      'to': config.toLanguageId,
      'enable_tts': false,
      'is_domestic': false,
      'audio_type': 'pcm',
      'timeout': 300,
      'user_id': '',
      'device_code': '',
      'caller': 'vike',
    };
    _socket?.add(jsonEncode({'parameter': params}));
  }

  void handleServerMessage(dynamic raw) {
    if (raw is! String) return;
    try {
      final json = jsonDecode(raw) as Map<String, dynamic>;
      if (json['success'] == true) return;

      final code = json['code'] as int?;
      if (code != 200) return;

      final asrResults = (json['data'] as Map?)?.get('asr_results') as Map?;
      if (asrResults == null) return;

      final text = asrResults['text'] as String? ?? '';
      final isFinal = asrResults['final_result'] as bool? ?? false;
      if (text.isEmpty) return;

      final current = List<InterpretationEntry>.from(state.entries);

      if (current.isNotEmpty && !current.last.isFinal) {
        current[current.length - 1] = current.last.copyWith(text: text, isFinal: isFinal);
      } else {
        current.add(InterpretationEntry(text: text, isFinal: isFinal));
      }

      state = state.copyWith(entries: current);
    } catch (error) {
      state = state.copyWith(
        error: InterpretationError(
          kind: InterpretationErrorKind.parseFailed,
          detail: error.toString(),
        ),
      );
    }
  }

  void _onSocketError(Object error) {
    state = InterpretationState(
      status: InterpretationStatus.error,
      entries: state.entries,
      error: InterpretationError(
        kind: InterpretationErrorKind.socketError,
        detail: error.toString(),
      ),
    );
  }

  void _onSocketDone() {
    if (state.isRunning) {
      state = state.copyWith(status: InterpretationStatus.idle);
    }
  }

  Future<void> _closeSocket() async {
    try {
      await _socket?.close();
    } catch (_) {}
    _socket = null;
  }
}

final interpretationControllerProvider =
    NotifierProvider<InterpretationController, InterpretationState>(
  InterpretationController.new,
);

extension on Map {
  dynamic get(String key) => this[key];
}
