import 'glasses_event.dart';

/// Parses raw BLE Notify bytes into [GlassesEvent]s.
///
/// Frame layout: `[0xEA, lenLo, lenHi, 0x00, id, subId, ...payload]`
/// Returns null for frames that don't match the 0xEA header or are too short.
abstract final class GlassesResponseParser {
  static const _header = 0xEA;
  static const _minLength = 6;

  /// Parses [frame] into a [GlassesEvent], or returns null if invalid.
  static GlassesEvent? parse(List<int> frame) {
    if (frame.length < _minLength) return null;
    if (frame[0] != _header) return null;

    final id = frame[4];
    final subId = frame[5];
    final payload = frame.length > _minLength ? frame.sublist(_minLength) : const <int>[];
    return GlassesRawEvent(id: id, subId: subId, payload: payload);
  }
}
