import 'glasses_transport_defaults.dart';

/// GATT targets for glasses command writes. UUIDs vary by chip — inject from App.
class GlassesTransportConfig {
  /// Creates transport configuration for protocol writes.
  const GlassesTransportConfig({
    this.serviceUuid = GlassesTransportDefaults.serviceUuid,
    this.writeCharacteristicUuid =
        GlassesTransportDefaults.writeCharacteristicUuid,
    this.notifyCharacteristicUuid =
        GlassesTransportDefaults.notifyCharacteristicUuid,
  });

  /// BLE service UUID for command channel.
  final String serviceUuid;

  /// Writable characteristic UUID.
  final String writeCharacteristicUuid;

  /// Notify characteristic UUID (reserved for response parsing).
  final String notifyCharacteristicUuid;

  /// Whether write targets are configured.
  bool get isConfigured =>
      serviceUuid.isNotEmpty && writeCharacteristicUuid.isNotEmpty;
}
